import {chromium} from 'playwright';
import assert from 'node:assert/strict';
import fs from 'node:fs';
const base='https://browser-game-arcade.vercel.app';
const game=base+'/play/deep-dive/index-public-art.html';
const browser=await chromium.launch({headless:true,args:['--disable-dev-shm-usage']});
const tests=[],exceptions=[];
const stamp=Date.now().toString().slice(-8);
const report=(name,status,detail='')=>{tests.push({name,status,detail});console.log('[QA]',status,name,detail);};
async function check(name,fn){try{const res=await fn();report(name,'PASS',String(res??'').slice(0,250))}catch(e){report(name,'FAIL',e.message?.slice(0,750)||String(e));}}
const ctx=async(options={})=>browser.newContext({viewport:{width:1440,height:900},permissions:['clipboard-read','clipboard-write'],...options});
const pageErrors=p=>p.on('pageerror',e=>exceptions.push(e.message));
const ready=async(p)=>{await p.goto(game,{waitUntil:'domcontentloaded',timeout:40000});await p.locator('.deep-home[data-phase=intro]').waitFor({timeout:35000});await p.waitForFunction(()=>!document.getElementById('dd-boot')||getComputedStyle(document.getElementById('dd-boot')).visibility==='hidden',{timeout:20000}).catch(()=>{});};
const nav=async(p,view)=>{const menu=p.locator('.dd-source-menu-backdrop');if(await menu.getAttribute('data-open')!=='true')await p.locator('.dd-nav-toggle>summary').click();await p.locator('.dd-source-menu-link[data-menu-view="'+view+'"]').click();await p.locator('.dd-source-menu-backdrop').waitFor({state:'hidden',timeout:12000});};
const request=async(url)=>{const r=await fetch(base+url,{signal:AbortSignal.timeout(25000)});assert.equal(r.status,200,url+' http '+r.status);return r.json()};
const a=await ctx(),p=await a.newPage();pageErrors(p);
try{
 await check('Homepage initial boot and load',async()=>{await ready(p);assert(await p.locator('.dd-logo').first().isVisible());assert(await p.locator('.dd-begin').isVisible());assert.equal(await p.locator('#dd-boot').count(),0);return 'boot dismissed; hero visible'});
 await check('Homepage logo, ocean and motion',async()=>{const v=await p.evaluate(()=>({letters:document.querySelectorAll('.dd-logo span').length,sea:!!document.querySelector('.dd-reference-sea-canvas'),animated:getComputedStyle(document.querySelector('.deep-home .dd-logo span')).animationName,water:getComputedStyle(document.querySelector('.dd-sky'),'::after').animationName}));assert(v.letters>=8);assert(v.sea);assert(v.animated!=='none');assert(v.water!=='none');return JSON.stringify(v)});
 await check('Menu, Escape, outside click, FAQ',async()=>{await p.locator('.dd-nav-toggle>summary').click();await p.locator('.dd-source-menu-panel').waitFor();await p.locator('.dd-source-menu-faq>summary').click();assert(await p.locator('.dd-source-menu-faq').getAttribute('open')!==null);await p.keyboard.press('Escape');assert.equal(await p.locator('.dd-source-menu-backdrop').getAttribute('data-open'),'false');await p.locator('.dd-nav-toggle>summary').click();await p.locator('[data-close-menu]').click();assert.equal(await p.locator('.dd-source-menu-backdrop').getAttribute('data-open'),'false')});
 await check('Sound toggle and persistence',async()=>{const b=p.locator('[data-dd-sound]');await b.click();const one=await b.getAttribute('aria-label');await b.click();const two=await b.getAttribute('aria-label');assert.notEqual(one,two);await p.reload();await p.locator('[data-dd-sound]').waitFor();assert.equal(await p.locator('[data-dd-sound]').getAttribute('aria-label'),two);return one+' -> '+two});
  for(const key of ['lowPower','contrast','answerCorrections','clearRejected']){
  await check('Settings '+key+' persists across reload',async()=>{
   await p.locator('.dd-reference-preferences>summary').click();
   const box=p.locator('[data-dd-setting="'+key+'"]');const old=await box.isChecked();
   await box.setChecked(!old);const chosen=await box.isChecked();
   await p.reload();await p.locator('.deep-home[data-phase=intro]').waitFor({timeout:22000});
   await p.locator('.dd-reference-preferences>summary').click();
   const retained=await p.locator('[data-dd-setting="'+key+'"]').isChecked();
   await p.locator('[data-dd-setting="'+key+'"]').setChecked(old);
   await p.locator('.dd-reference-preferences>summary').click();
   assert.equal(retained,chosen,'preference key '+key+' not retained');return 'saved='+chosen+' restored='+retained;
  });
 }
 await check('Characters locking and mascot poke',async()=>{await p.locator('.dd-reference-preferences>summary').click();const opts=await p.locator('[data-dd-character] option').evaluateAll(os=>os.map(o=>({text:o.textContent,disabled:o.disabled})));assert.equal(opts.length,5);assert(opts.slice(1).every(x=>x.disabled));await p.locator('.dd-reference-preferences>summary').click();return opts.map(x=>x.disabled?'locked':'ready').join(', ')});
 await check('Daily start, preview and answer UI',async()=>{await nav(p,'daily');await p.locator('.dd-begin').click();await p.locator('#answer-input').waitFor({timeout:12000});assert(await p.locator('.dd-hud').isVisible());assert(await p.locator('#seconds').isVisible());assert(await p.locator('.dd-dive-btn').isDisabled());return await p.locator('.dd-prompt-text').first().innerText()});
 await check('Daily resume after reload',async()=>{const initial=await p.locator('.dd-prompt-text').first().innerText();await p.reload();await p.locator('.dd-game-screen').waitFor({timeout:20000});assert.equal(await p.locator('.dd-prompt-text').first().innerText(),initial);return 'active daily preserved'});
}finally{await a.close()}
const unlimited=await ctx(),u=await unlimited.newPage();pageErrors(u);
try{
 await check('Unlimited 7/7 scored prompts, descent and completed results',async()=>{
 const free=await request('/play/deep-dive/recovered/free-starters.json');let sheets=free.modes.unlimited.questions;assert.equal(sheets.length,7);
 await ready(u);await nav(u,'endless');await u.locator('.dd-begin').click();
 let total=0;for(let i=0;i<7;i++){await u.locator('#answer-input').waitFor({timeout:18000});const prompt=(await u.locator('.dd-prompt-text').first().innerText()).trim();const q=sheets.find(x=>x.text===prompt);assert(q,'Missing starter prompt '+prompt);let ans=q.answers.find(x=>x[1]>=10)||q.answers[0];assert(ans,'no answers for '+prompt);await u.locator('#answer-input').fill(ans[0]);await u.locator('.dd-dive-btn').click();await u.locator('.dd-next-btn').waitFor({timeout:10000});const feedback=await u.locator('.dd-reveal').innerText();assert(!/NOTHING LANDED/i.test(feedback),'Known published answer rejected: '+ans[0]+' '+feedback.slice(0,140));total+=Number(ans[1]);await u.locator('.dd-next-btn').click();}await u.locator('.dd-done-inner').waitFor({timeout:25000});assert.equal(await u.locator('.dd-catch-row').count(),7);const score=await u.locator('.dd-done-score .big').innerText();assert.equal(Number(score.replace(/\D/g,'')),total);return '7 accepted; total '+total+'; seven catch rows'});
 await check('Results filters, rating, copy, continue',async()=>{await u.locator('.dd-catch-row').first().locator('summary').click();await u.locator('.dd-catch-row').first().locator('.dd-catch-search').fill('a');const tier=u.locator('.dd-catch-row').first().locator('.dd-catch-tier');await tier.selectOption('5');await u.locator('[data-action=rate][data-rating="4"]').click();assert(await u.locator('.dd-rate[data-rating="4"]').evaluate(x=>x.classList.contains('on')));await u.locator('[data-action=share]').click();await u.locator('[data-action=share]').filter({hasText:/COPIED/}).waitFor({timeout:5000});await u.locator('[data-action=startEndless]').click();await u.locator('.dd-game-screen').waitFor({timeout:16000});return 'filter/rate/copy and next mode started'});
}finally{await unlimited.close()}
const worlds=await ctx(),w=await worlds.newPage();pageErrors(w);
try{
 await check('All themed pack chapters and lock states',async()=>{await ready(w);await nav(w,'worlds');for(const mode of ['lexicon','movies','sports','geography']){const card=w.locator('.dd-source-pack[data-pack="'+mode+'"]');assert(await card.isVisible());await card.locator('details summary').click();assert.equal(await card.locator('.dd-public-chapter-list button').count(),30);const count=await card.locator('.dd-public-chapter-list button:not(:disabled)').count();assert(count<=1,'unexpected unlocked paid chapters');}return '4 packs, 120 chapter buttons; only verified starters enabled'});
 for(const mode of ['movies','sports','geography','lexicon']){
 await check('Themed '+mode+' starter, scoring/timeout state',async()=>{await nav(w,'worlds');const card=w.locator('.dd-source-pack[data-pack="'+mode+'"]');const b=card.locator('[data-action=startStarter]').first();if(!await b.count())return 'SKIP: no verified scores provided';await b.click();await w.locator('#answer-input').waitFor({timeout:20000});assert(await w.locator('.dd-hud').isVisible());const scene=await w.locator('.dd-game-screen').getAttribute('data-world');assert(scene);return 'prompt '+(await w.locator('.dd-prompt-text').first().innerText())+' world='+scene});
 }
 await check('Practice worlds open and locked',async()=>{await nav(w,'worlds');await w.locator('.dd-practice-collapse>summary').click();const cards=w.locator('.world-card');assert(await cards.count()>=9);const first=cards.first();assert(await first.locator('.chapter').first().isEnabled());assert(await first.locator('.chapter').nth(1).isDisabled());await first.locator('.chapter').first().click();await w.locator('#answer-input').waitFor({timeout:18000});return 'chapter 1 played; chapter 2 locked'});
}finally{await worlds.close()}
const archive=await ctx(),ar=await archive.newPage();pageErrors(ar);
try{
 await check('Archive 105 index entries and first/last navigation',async()=>{await ready(ar);await nav(ar,'archive');const b=ar.locator('.dd-archive-date');assert.equal(await b.count(),105);const months=await ar.locator('.dd-archive-month').count();assert(months>=4);await b.last().click();await ar.locator('#answer-input').waitFor({timeout:18000});assert(await ar.locator('.dd-hud').isVisible());return months+' months; 105 buttons; first historic dive starts'});
 await check('Archive all recovered snapshot integrity (105)',async()=>{const manifest=await request('/play/deep-dive/recovered/archive/manifest.json');assert.equal(manifest.dates.length,105);let checked=0;for(let i=0;i<manifest.dates.length;i+=8){const group=manifest.dates.slice(i,i+8);const replies=await Promise.all(group.map(async x=>{const r=await fetch(base+'/play/deep-dive/recovered/archive/'+x.date+'.json',{signal:AbortSignal.timeout(25000)});assert.equal(r.status,200,x.date);const j=await r.json();assert.equal(j.questions.length,7,x.date);assert(j.questions.every(q=>q.answers.length>0),x.date+' missing answers');return 1}));checked+=replies.reduce((a,b)=>a+b,0)}return checked+' snapshots with 735 seven-round prompts'});
 await check('Archive return to Daily',async()=>{await nav(ar,'archive');await ar.locator('.dd-archive-return').click();assert(await ar.locator('.deep-home[data-mode=daily]').isVisible());});
}finally{await archive.close()}
const mc=await ctx({viewport:{width:390,height:844},isMobile:true,deviceScaleFactor:2,hasTouch:true}),m=await mc.newPage();pageErrors(m);
try{
 await check('Mobile menu, homepage, no sideways overflow',async()=>{await ready(m);const box=await m.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth}));assert(box.scroll<=box.width+12,JSON.stringify(box));await m.locator('.dd-nav-toggle>summary').click();assert(await m.locator('.dd-source-menu-panel').isVisible());await m.keyboard.press('Escape');return JSON.stringify(box)});
 await check('Mobile Puffer Party controls and vertical scroll',async()=>{await nav(m,'party');await m.locator('.pp-view').waitFor();for(const sel of ['#pp-name','.pp-capacity-grid','.pp-host-btn','.pp-join-form','.pp-public-panel'])assert(await m.locator(sel).count());const d=await m.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth}));assert(d.scroll<=d.width+16,JSON.stringify(d));return JSON.stringify(d)});
 await check('Mobile Archive, Packs and Settings',async()=>{for(const view of ['archive','worlds','daily']){await nav(m,view);assert(await m.locator('#app section').first().isVisible())}await m.locator('.dd-reference-preferences>summary').click();assert(await m.locator('.dd-reference-settings-panel').isVisible());return 'three views and settings'});
}finally{await mc.close()}
const party=await ctx(),peer=await ctx(),h=await party.newPage(),g=await peer.newPage();pageErrors(h);pageErrors(g);
let host=null,guest=null,room=null;
const partyRequest=async(body,method='POST')=>{const resp=await party.request.fetch(base+'/api/deep-dive/party',{method,data:body,headers:{'Content-Type':'application/json'},timeout:30000});const raw=await resp.json().catch(()=>({}));if(!resp.ok())throw Error('API '+resp.status()+' '+JSON.stringify(raw));return raw};
try{
 await check('Multiplayer public listing API',async()=>{const r=await party.request.get(base+'/api/deep-dive/party?list=1');assert.equal(r.status(),200,'GET list '+r.status());assert(Array.isArray((await r.json()).rooms));return 'GET list 200'});
 await check('Multiplayer two-browser host/join and lobby',async()=>{await ready(h);await nav(h,'party');await h.locator('#pp-name').fill('QAHost'+stamp);await h.locator('.pp-capacity[data-capacity="2"]').click();await h.locator('.pp-host-btn').click();await h.locator('.pp-code').waitFor({timeout:18000});room=(await h.locator('.pp-code').innerText()).trim();assert.equal(room.length,6);await ready(g);await nav(g,'party');await g.locator('#pp-name').fill('QAGuest'+stamp);await g.locator('#pp-code').fill(room);await g.locator('.pp-join-form [data-party=join]').click();await g.locator('[data-party=ready]').waitFor({timeout:20000});await g.locator('[data-party=ready]').click();await h.locator('[data-party=start]').waitFor({timeout:18000});return 'room '+room+' created, guest ready'});
 await check('Multiplayer host starts, two peers sync prompt',async()=>{await h.locator('[data-party=start]').click();await h.locator('.pp-heading h1').waitFor({timeout:18000});await g.locator('.pp-heading h1').waitFor({timeout:18000});assert.equal(await h.locator('.pp-heading h1').innerText(),await g.locator('.pp-heading h1').innerText());return await h.locator('.pp-heading h1').innerText()});
 await check('Multiplayer answer/duplicate/turn progression',async()=>{const bank=await request('/play/deep-dive/questions.json');const prompt=await h.locator('.pp-heading h1').innerText();const q=bank.questions.find(x=>x.prompt===prompt);assert(q,'question not in local bank');await h.locator('#pp-answer-input').fill(q.answers[0].value);await h.locator('#pp-answer button[type=submit]').click();await g.locator('#pp-answer-input').waitFor({timeout:15000});await g.locator('#pp-answer-input').fill(q.answers[0].value);await g.locator('#pp-answer button[type=submit]').click();await g.locator('.pp-error').filter({hasText:/already been used/i}).waitFor({timeout:13000});await g.locator('[data-party=dismiss]').click();const alternative=q.answers.find(x=>x.value!==q.answers[0].value);assert(alternative);await g.locator('#pp-answer-input').fill(alternative.value);await g.locator('#pp-answer button[type=submit]').click();await h.waitForFunction(p=>document.querySelector('.pp-heading h1')?.textContent!==p,prompt,{timeout:18000});return 'answer accepted, duplicate rejected, next turn/question'});
 await check('Multiplayer chat, pass, leave',async()=>{await h.locator('#pp-message').fill('QA two browser chat '+stamp);await h.locator('#pp-chat button[type=submit]').click();await g.locator('.pp-chat').filter({hasText:stamp}).waitFor({timeout:12000});const passed=await h.locator('[data-party=pass]').count();if(passed)await h.locator('[data-party=pass]').click();await g.locator('[data-party=leave]').click();await g.locator('.pp-identity-panel').waitFor({timeout:13000});return 'chat synchronized, guest left; pass clickable='+Boolean(passed)});
 }finally{if(room){const rooms=await party.request.get(base+'/api/deep-dive/party?code='+room).then(x=>x.json()).catch(()=>({}));console.log('QA_ROOM_REMAINS',room,rooms.room?.phase||'unavailable')}await party.close();await peer.close()}
await browser.close();
const counts=tests.reduce((x,t)=>(x[t.status]=(x[t.status]||0)+1,x),{});
fs.writeFileSync('deep-dive-full-qa-results.json',JSON.stringify({date:new Date().toISOString(),base,counts,tests,pageErrors:exceptions},null,2));
console.log('QA_RESULTS',JSON.stringify({counts,tests,pageErrors:exceptions}));
if(counts.FAIL)process.exitCode=1;